from typing import List, Dict, Any

class ExtractedText:
    def __init__(self, text: str, page_number: int = None):
        self.text = text
        self.page_number = page_number

    def to_dict(self):
        return {"text": self.text, "page_number": self.page_number}

class ExtractedLayout:
    def __init__(self, blocks: List[Dict[str, Any]], page_number: int = None):
        self.blocks = blocks
        self.page_number = page_number

    def to_dict(self):
        return {"blocks": self.blocks, "page_number": self.page_number}

class ExtractedTable:
    def __init__(self, cells: List[Dict[str, Any]], row_count: int, column_count: int, page_number: int = None):
        self.cells = cells
        self.row_count = row_count
        self.column_count = column_count
        self.page_number = page_number

    def to_dict(self):
        return {
            "cells": self.cells,
            "row_count": self.row_count,
            "column_count": self.column_count,
            "page_number": self.page_number
        }

class ExtractedKeyValue:
    def __init__(self, key: str, value: str, page_number: int = None):
        self.key = key
        self.value = value
        self.page_number = page_number

    def to_dict(self):
        return {"key": self.key, "value": self.value, "page_number": self.page_number}

from document_client import get_document_analysis_client
from document_models import ExtractedText
from azure.ai.vision.imageanalysis.models import VisualFeatures

def extract_text_from_image(image_data: bytes) -> ExtractedText:
    client = get_document_analysis_client()

    # The SDK provides options for local file path or URL for image sources.
    # Assuming image_data is raw image bytes.
    # For a real scenario, you might pass a stream or file path.
    result = client.analyze(image_data, visual_features=[VisualFeatures.READ])

    full_text = []
    if result.read and result.read.blocks:
        for block in result.read.blocks:
            for line in block.lines:
                full_text.append(line.text)

    return ExtractedText(text="\n".join(full_text))

from document_client import get_document_analysis_client
from document_models import ExtractedLayout
from azure.ai.vision.imageanalysis.models import VisualFeatures

def extract_layout_from_image(image_data: bytes) -> ExtractedLayout:
    client = get_document_analysis_client()

    result = client.analyze(image_data, visual_features=[VisualFeatures.READ])

    blocks_data = []
    if result.read and result.read.blocks:
        for block in result.read.blocks:
            block_info = {
                "text": block.text,
                "bounding_box": [(p.x, p.y) for p in block.bounding_box],
                "lines": []
            }
            for line in block.lines:
                line_info = {
                    "text": line.text,
                    "bounding_box": [(p.x, p.y) for p in line.bounding_box],
                    "words": []
                }
                if line.words:
                    for word in line.words:
                        line_info["words"].append({
                            "text": word.text,
                            "bounding_box": [(p.x, p.y) for p in word.bounding_box],
                            "confidence": word.confidence
                        })
                block_info["lines"].append(line_info)
            blocks_data.append(block_info)

    return ExtractedLayout(blocks=blocks_data)

